-- ══════════════════════════════════════════════
-- VERIFICACIÓN FINAL
-- ══════════════════════════════════════════════
SELECT 
  CASE 
    WHEN nombre LIKE 'Tropicana%' THEN '🔴 Tropicana'
    WHEN nombre LIKE 'Radio Uno%' THEN '🟠 Radio Uno'
    WHEN nombre LIKE 'La Mega%'   THEN '🟡 La Mega'
    WHEN nombre LIKE 'El Sol%'    THEN '🌞 El Sol'
    WHEN nombre LIKE 'La Reina%'  THEN '👑 La Reina'
    WHEN nombre LIKE 'Olímpica%'  THEN '🔵 Olímpica'
    ELSE '📻 Otra'
  END AS cadena,
  COUNT(*) AS total
FROM emisoras
GROUP BY 1
ORDER BY 1;
